{"explanation":"The function y = A sin(B(x − C)) + D has four knobs: A is the amplitude (height of the wave), B controls the frequency (period = 2π/B), C is the phase shift (slides the wave left/right), and D is the vertical shift (moves the midline up/down). The faint gray curve is the reference y = sin(x), the dashed gray line is the midline y = D, and the gold dot marks (C, D) — the point where each cycle begins. Use the sliders to morph the blue wave and watch the equation and stats update live.","manimCode":"const TWO_PI = 2 * Math.PI;

// State
let A = 1, B = 1, C = 0, D = 0;
const fn = x => A * Math.sin(B * (x - C)) + D;

// Axes (symmetric y-range so y = 0 sits on the horizontal axis)
const axes = new Axes({
  xRange: [-TWO_PI, TWO_PI, Math.PI],
  yRange: [-4.2, 4.2, 1],
  xLength: 10,
  yLength: 6,
  tips: false
});
axes.moveTo([-1.2, 0, 0]);
const axisLabels = axes.getAxisLabels();

// Reference curve y = sin(x)
const refCurve = axes.plot(x => Math.sin(x), { color: GRAY, numSamples: 500 });
refCurve.setOpacity(0.35);

// Main curve
let curve = axes.plot(fn, { color: BLUE, numSamples: 500 });

// Midline y = D (2-vertex polygon line)
const midline = new Polygon({
  vertices: [axes.c2p(-TWO_PI, D), axes.c2p(TWO_PI, D)],
  color: GRAY
});
midline.setStrokeWidth(1.5);
midline.setFillOpacity(0);
midline.setOpacity(0.7);

// Gold dot at (C, D): start of the cycle
const goldDot = new Dot({ point: axes.c2p(C, D), color: GOLD });

// Labels
function buildEq() {
  const cZero = Math.abs(C) < 0.05;
  const inner = cZero ? 'x' : (C > 0 ? `x - ${C.toFixed(1)}` : `x + ${(-C).toFixed(1)}`);
  const dStr = Math.abs(D) < 0.05 ? '' : (D > 0 ? ` + ${D.toFixed(1)}` : ` - ${(-D).toFixed(1)}`);
  return `y = ${A.toFixed(1)} sin(${B.toFixed(1)}(${inner}))${dStr}`;
}
function buildInfo() {
  return `Amplitude = ${Math.abs(A).toFixed(1)}     Period = ${(TWO_PI / B).toFixed(2)}     Phase shift = ${C.toFixed(1)}     Midline: y = ${D.toFixed(1)}`;
}

let eqText = new Text({ text: buildEq(), color: WHITE, fontSize: 26 });
eqText.moveTo([-1.2, 3.45, 0]);
let infoText = new Text({ text: buildInfo(), color: GRAY, fontSize: 20 });
infoText.moveTo([-1.2, -3.4, 0]);
const refLabel = new Text({ text: 'y = sin(x)', color: GRAY, fontSize: 18 });
refLabel.moveTo(axes.c2p(-5.2, 1.7));

// Intro
await scene.play(new Create(axes));
scene.add(axisLabels);
await scene.play(new FadeIn(refCurve));
await scene.play(new Create(curve));
await scene.play(new AnimationGroup([
  new FadeIn(midline),
  new FadeIn(goldDot),
  new Write(eqText),
  new FadeIn(infoText),
  new FadeIn(refLabel)
]));

// Rebuild everything that depends on A, B, C, D
function refresh() {
  scene.remove(curve);
  curve = axes.plot(fn, { color: BLUE, numSamples: 500 });
  scene.add(curve);

  midline.setVertices([axes.c2p(-TWO_PI, D), axes.c2p(TWO_PI, D)]);

  goldDot.moveTo(axes.c2p(C, D));
  scene.remove(goldDot);
  scene.add(goldDot);

  scene.remove(eqText);
  eqText = new Text({ text: buildEq(), color: WHITE, fontSize: 26 });
  eqText.moveTo([-1.2, 3.45, 0]);
  scene.add(eqText);

  scene.remove(infoText);
  infoText = new Text({ text: buildInfo(), color: GRAY, fontSize: 20 });
  infoText.moveTo([-1.2, -3.4, 0]);
  scene.add(infoText);
}

// Sliders
const controls = new Controls(scene, { position: 'top-right', width: 260 });
controls.addSlider({ label: 'A  (amplitude)', min: 0, max: 2.5, value: 1, step: 0.1, onChange: v => { A = v; refresh(); } });
controls.addSlider({ label: 'B  (frequency)', min: 0.2, max: 4, value: 1, step: 0.1, onChange: v => { B = v; refresh(); } });
controls.addSlider({ label: 'C  (phase shift)', min: -3, max: 3, value: 0, step: 0.1, onChange: v => { C = v; refresh(); } });
controls.addSlider({ label: 'D  (vertical shift)', min: -1.5, max: 1.5, value: 0, step: 0.1, onChange: v => { D = v; refresh(); } });

await scene.wait(999999);"}

